"""CIRCT-style ``hw`` dialect: module structure, ports, constants, outputs."""

from enum import Enum


class IntType:
    """Signless integer hardware type, e.g. ``i4``."""

    def __init__(self, width):
        self.width = int(width)

    def mask(self):
        return (1 << self.width) - 1

    def __eq__(self, other):
        return isinstance(other, IntType) and other.width == self.width

    def __hash__(self):
        return hash(("hw.int", self.width))

    def __repr__(self):
        return f"i{self.width}"


class Direction(Enum):
    INPUT = "in"
    OUTPUT = "out"


class Port:
    """A named, typed port on a hardware module."""

    def __init__(self, name, port_type, direction):
        self.name = name
        self.port_type = port_type
        self.direction = direction

    def __repr__(self):
        return (f"Port({self.direction.value} %{self.name}: "
                f"{self.port_type})")


class HWModuleOp:
    """A hardware module: a name, a port list and a body of ops."""

    def __init__(self, name, ports, body):
        self.name = name
        self.ports = list(ports)
        self.body = list(body)

    @property
    def input_ports(self):
        return [p for p in self.ports if p.direction is Direction.INPUT]

    @property
    def output_ports(self):
        return [p for p in self.ports if p.direction is Direction.OUTPUT]

    def __repr__(self):
        return f"HWModuleOp(@{self.name}, ports={len(self.ports)})"


class ConstantOp:
    """``hw.constant``: produces a compile-time integer value."""

    def __init__(self, value, width, result_name=None):
        self.value = int(value)
        self.width = int(width)
        self.result_name = result_name

    def evaluate(self, env=None):
        return self.value & ((1 << self.width) - 1)

    def __repr__(self):
        return f"ConstantOp({self.value} : i{self.width})"


class OutputOp:
    """``hw.output``: terminator driving the module's output ports."""

    def __init__(self, operands):
        self.operands = list(operands)

    def __repr__(self):
        return f"OutputOp({self.operands})"

"""CIRCT-style ``comb`` dialect: combinational arithmetic/logic ops.

Every op takes a list of operand *names* (SSA value names or port names),
a result ``width`` and an optional ``result_name``.  ``evaluate(env)``
looks the operands up in ``env`` and returns the result masked to the
op's width.
"""


def _mask(width):
    return (1 << width) - 1


class CombOp:
    """Base class for combinational ops."""

    def __init__(self, operands, width, result_name=None):
        self.operands = list(operands)
        self.width = int(width)
        self.result_name = result_name

    def _values(self, env):
        return [env[name] for name in self.operands]

    def evaluate(self, env):
        raise NotImplementedError

    def __repr__(self):
        return (f"{type(self).__name__}({self.operands} : "
                f"i{self.width})")


class AddOp(CombOp):
    def evaluate(self, env):
        a, b = self._values(env)
        return (a + b) & _mask(self.width)


class SubOp(CombOp):
    def evaluate(self, env):
        a, b = self._values(env)
        return (a - b) & _mask(self.width)


class MulOp(CombOp):
    def evaluate(self, env):
        a, b = self._values(env)
        return (a * b) & _mask(self.width)


class AndOp(CombOp):
    def evaluate(self, env):
        a, b = self._values(env)
        return (a & b) & _mask(self.width)


class OrOp(CombOp):
    def evaluate(self, env):
        a, b = self._values(env)
        return (a | b) & _mask(self.width)


class XorOp(CombOp):
    def evaluate(self, env):
        a, b = self._values(env)
        return (a ^ b) & _mask(self.width)


class MuxOp(CombOp):
    """2:1 mux: ``operands = [sel, if_true, if_false]``."""

    def evaluate(self, env):
        sel, if_true, if_false = self._values(env)
        result = if_true if sel else if_false
        return result & _mask(self.width)

"""CIRCT-style ``seq`` dialect: sequential (state-holding) ops."""


def _mask(width):
    return (1 << width) - 1


class CompRegOp:
    """``seq.compreg``: a register capturing its input on each clock tick.

    ``input_signal`` is the name of the value sampled on a tick.  Optional
    ``reset_signal``/``reset_value`` give synchronous-reset semantics: when
    the named reset signal is truthy in the tick environment, the register
    loads ``reset_value`` (which may itself be an env name or an int)
    instead of the input.
    """

    def __init__(self, name, width, input_signal,
                 reset_signal=None, reset_value=None):
        self.name = name
        self.width = int(width)
        self.input_signal = input_signal
        self.reset_signal = reset_signal
        self.reset_value = reset_value
        self._value = 0

    def get_value(self):
        return self._value

    def tick(self, env):
        """Advance one clock cycle: capture the input (or reset value)."""
        if self.reset_signal is not None and env.get(self.reset_signal):
            if isinstance(self.reset_value, str):
                self._value = env[self.reset_value] & _mask(self.width)
            else:
                self._value = (self.reset_value or 0) & _mask(self.width)
        else:
            self._value = env[self.input_signal] & _mask(self.width)
        return self._value

    def __repr__(self):
        return f"CompRegOp(%{self.name} : i{self.width}, value={self._value})"

"""Cycle-accurate simulator for parsed ``hw.module`` circuits.

Reuses the mini-MLIR parser (``mlir.parser.parse``) to read ``hw``/``comb``
/``seq`` dialect text, elaborates the parsed operations into an executable
circuit of circt dialect objects, and simulates it cycle by cycle:

* within a cycle, combinational logic is evaluated to a fixpoint;
* on the clock tick, ``seq.compreg`` registers capture their input,
  honouring synchronous reset.
"""

from mlir.parser import parse

from circt.hw_dialect import (
    ConstantOp, Direction, HWModuleOp, IntType, OutputOp, Port,
)
from circt.comb_dialect import AddOp, AndOp, MuxOp, MulOp, OrOp, SubOp, XorOp
from circt.seq_dialect import CompRegOp

_COMB_CLASSES = {
    "comb.add": AddOp,
    "comb.sub": SubOp,
    "comb.mul": MulOp,
    "comb.and": AndOp,
    "comb.or": OrOp,
    "comb.xor": XorOp,
    "comb.mux": MuxOp,
}


def _width_of(op):
    """Result width of a parsed op, from its trailing ``: iN`` type."""
    type_str = op.attributes["types"][0]
    return int(type_str.lstrip("i"))


def _names(values):
    return [v.name.lstrip("%") for v in values]


class _ICmp:
    """``comb.icmp`` (eq/ne only, enough for the ALU selector logic)."""

    def __init__(self, predicate, operands, width, result_name):
        self.predicate = predicate
        self.operands = operands
        self.width = width
        self.result_name = result_name

    def evaluate(self, env):
        a, b = (env[n] for n in self.operands)
        if self.predicate == "eq":
            return int(a == b)
        if self.predicate == "ne":
            return int(a != b)
        raise ValueError(f"unsupported icmp predicate: {self.predicate}")


def elaborate(parsed_module, module_name=None):
    """Elaborate a parsed MLIR module into an executable HWModuleOp.

    ``parsed_module`` may be a ``mlir.ir.Module`` or raw MLIR text.
    Returns ``(HWModuleOp, registers)`` where ``registers`` maps SSA result
    names to the live ``CompRegOp`` objects holding the state.
    """
    if isinstance(parsed_module, str):
        parsed_module = parse(parsed_module)

    hw_op = None
    for op in parsed_module.ops:
        if op.name == "hw.module" and (
                module_name is None
                or op.attributes.get("sym_name") == module_name):
            hw_op = op
            break
    if hw_op is None:
        raise ValueError("no hw.module found in parsed module")

    ports = []
    for p in hw_op.attributes["ports"]:
        direction = (Direction.INPUT if p["dir"] == "in"
                     else Direction.OUTPUT)
        port_type = p["type"]
        if port_type.startswith("i"):
            port_type = IntType(int(port_type[1:]))
        ports.append(Port(p["name"], port_type, direction))

    body = []
    registers = {}
    block = hw_op.regions[0].blocks[0]
    for op in block.ops:
        operands = _names(op.operands)
        result_name = op.results[0].name.lstrip("%") if op.results else None
        if op.name in _COMB_CLASSES:
            body.append(_COMB_CLASSES[op.name](
                operands=operands, width=_width_of(op),
                result_name=result_name))
        elif op.name == "comb.icmp":
            body.append(_ICmp(op.attributes["predicate"], operands,
                              _width_of(op), result_name))
        elif op.name == "hw.constant":
            body.append(ConstantOp(op.attributes["value"], _width_of(op),
                                   result_name=result_name))
        elif op.name == "seq.compreg":
            width = _width_of(op)
            if op.attributes.get("reset"):
                reg = CompRegOp(name=result_name, width=width,
                                input_signal=operands[0],
                                reset_signal=operands[2],
                                reset_value=operands[3])
            else:
                reg = CompRegOp(name=result_name, width=width,
                                input_signal=operands[0])
            body.append(reg)
            registers[result_name] = reg
        elif op.name == "hw.output":
            body.append(OutputOp(operands))
        else:
            raise ValueError(f"unsupported op in hw.module body: {op.name}")

    module = HWModuleOp(hw_op.attributes["sym_name"], ports, body)
    return module, registers


class Simulator:
    """Cycle-accurate simulator for an elaborated ``hw.module``.

    Usage::

        sim = Simulator(parse(open("counter.mlir").read()))
        outputs = sim.step({"reset": 1})   # one clock cycle
        outputs = sim.step({"reset": 0})
    """

    def __init__(self, parsed_module, module_name=None):
        self.module, self.registers = elaborate(parsed_module, module_name)
        self.cycle = 0

    # -- one-cycle combinational settle ------------------------------------

    def _settle(self, env):
        """Evaluate combinational logic to a fixpoint within one cycle."""
        for _ in range(len(self.module.body) + 2):
            changed = False
            for op in self.module.body:
                if isinstance(op, (OutputOp, CompRegOp)):
                    continue
                if not all(name in env for name in
                           getattr(op, "operands", [])):
                    continue
                value = op.evaluate(env)
                if env.get(op.result_name) != value:
                    env[op.result_name] = value
                    changed = True
            if not changed:
                break
        return env

    # -- public API ---------------------------------------------------------

    def step(self, inputs=None):
        """Simulate one clock cycle and return the output-port values.

        ``inputs`` maps input port names to integers.  The combinational
        network settles, outputs are sampled, then registers tick.
        """
        env = {}
        for name, reg in self.registers.items():
            env[name] = reg.get_value()
        for name, value in (inputs or {}).items():
            env[name] = int(value)

        env = self._settle(env)

        outputs = {}
        output_op = next(op for op in self.module.body
                         if isinstance(op, OutputOp))
        out_ports = self.module.output_ports
        for port, operand in zip(out_ports, output_op.operands):
            width = (port.port_type.width
                     if isinstance(port.port_type, IntType) else None)
            value = env[operand]
            outputs[port.name] = (value & ((1 << width) - 1)
                                  if width else value)

        for reg in self.registers.values():
            reg.tick(env)
        self.cycle += 1
        return outputs

    def run(self, inputs_per_cycle):
        """Run one cycle per entry of ``inputs_per_cycle``; return outputs."""
        return [self.step(inputs) for inputs in inputs_per_cycle]

    def reg_value(self, name):
        """Current state of the register with SSA result name ``name``."""
        return self.registers[name].get_value()

"""CIRCT-style hardware layer: hw/comb/seq dialects plus a simulator."""

